exam.solution:
def initials(full_name):
    parts = full_name.split()
    return parts[0][0].upper() + "." + parts[1][0].upper() + "."

def slugify(title):
    text = title.strip()
    if text[-1:] == '.':
        text = text[:-1]
    return '-'.join(text.lower().split())
